  test("rate versions scenario 3", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
    await ui.setSetting(pg_uma, "floor", "0.50");
    await ui.setSetting(pg_uma, "terms", "30");
    await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
    await ui.setSetting(pg_uma, "terms-C", "3");
    await ui.setSetting(pg_uma, "cap", "2.00");
    await ui.setSetting(pg_uma, "proof-threshold", "1.00");
    await ui.setSetting(pg_uma, "grace-days", "3");
    await ui.setSetting(pg_uma, "note-threshold", "2.50");
    await ui.setSetting(pg_uma, "grace-A", "2");
    expect(await ui.addVoidReason(pg_uma, "late")).toBe(true);
    expect(await ui.addVoidReason(pg_uma, "dup")).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50", "from": "2026-03-01", "to": "2026-03-25"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A", "tags": "b, a"}));
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B", "terms": "20"}));
    expect(await ui.addPool(pg_uma, "P1")).toBe(true);
    expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ada", "share": "33.33", "from": "2026-03-01", "to": "2026-04-30"})).toBe(true);
    expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ben", "share": "33.33", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    expect(await ui.delegate(pg_vic, {"user": "wes", "from": "2026-02-10", "to": "2026-03-09"})).toBe(true);
    const pg_wes = await ui.userPage(browser, "wes", sheet);
    const c_ben_0 = ui.must(await ui.addClaim(pg_wes, p_ben, {"amount": "7.77", "tags": "a"}));
    const c_ada_0 = ui.must(await ui.addClaim(pg_wes, p_ada, {"amount": "12.50", "date": "2026-03-05"}));
    const c_ada_1 = ui.must(await ui.addClaim(pg_wes, p_ada, {"amount": "25.00", "note": "n"}));
    expect(await ui.watch(pg_wes, p_ben, true)).toBe(true);
    const c_ada_2 = ui.must(await ui.addClaimTwice(pg_wes, p_ada, {"amount": "7.77", "date": "2026-03-15"}));
    expect(await ui.claimCount(pg_wes, p_ada)).toBe(3);
    expect(await ui.ratePreview(pg_wes, "B", "7.50")).toEqual({ count: 0, diff: "0.00" });
    await ui.refresh(pg_wes);
    await ui.sortBy(pg_wes, "added");
    expect(await ui.addHoliday(pg_wes, "2026-03-11")).toBe(true);
    expect(await ui.bulkOpen(pg_wes, [c_ada_1, c_ada_2])).toEqual({ opened: 2, refused: 0 });
    expect(await ui.setSettingDated(pg_wes, "note-threshold", "1.00", "2026-02-25", "2.50")).toBe(true);
    expect(await ui.claimAction(pg_wes, c_ben_0, "delete")).toBe(true);
    expect(await ui.claimAction(pg_wes, c_ben_0, "restore")).toBe(true);
    expect(await ui.claimEditOpen(pg_wes, c_ada_0)).toBe(true);
    await ui.refresh(pg_vic);
    expect(await ui.claimEditOpen(pg_vic, c_ada_0)).toBe(false);
    await ui.refresh(pg_wes);
    await ui.claimEditCancel(pg_wes, c_ada_0);
    expect(await ui.defer(pg_wes, c_ada_1, "2026-03-13")).toBe(true);
    await ui.refresh(pg_wes);

